/**
 * The few Material symbols Messages needs, drawn from their 24dp path data. The apps don't ship the
 * material-icons artifact, and one small file is lighter than adding it.
 */
internal object ChatIcons {
    private fun icon(name: String, vararg paths: String): ImageVector {
        val b = ImageVector.Builder(name, 24.dp, 24.dp, 24f, 24f)
        for (p in paths) b.addPath(PathParser().parsePathString(p).toNodes(), fill = SolidColor(Color.Black))
        return b.build()
    }

